   504→    # Loop control flow nodes
   505→    method build_loop_node($entry_control = undef) {
   506→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   507→        my $node_id = $self->next_node_id();
   508→        my $loop = Chalk::IR::Node::Loop->new(
   509→            id            => $node_id,
   510→            inputs        => [$ctrl],  # Entry control; backedge added later
   511→        );
   512→        $graph->add_node($loop);
   513→        return $loop;
   514→    }
   515→
   516→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   517→        # Loop phi starts with control and initial value
   518→        # Loop value added later (lazy phi pattern)
   519→        my @inputs = ($loop_node->id, $initial_value);
   520→        push(@inputs, $loop_value) if defined($loop_value);
   521→
   522→        my $node_id = $self->next_node_id();
   523→        my $phi = Chalk::IR::Node::Phi->new(
   524→            id            => $node_id,
   525→            inputs        => \@inputs,
   526→            region_id     => $loop_node->id,
   527→        );
   528→        $graph->add_node($phi);
   529→        return $phi;
   530→    }
   531→
   532→    # Function call nodes
   533→    method build_call_node($function_name, @arg_nodes) {
   534→        # Call: control, memory, arguments...
   535→        # For now, use current_control for both control and memory
   536→        my $attributes = { function => $function_name };
   537→        my $node_id = $self->next_node_id();
   538→        my $call = Chalk::IR::Node->new(
   539→            id            => $node_id,
   540→            op            => 'Call',
   541→            inputs        => [$current_control, $current_control, map { $_->id } @arg_nodes],
   542→            attributes    => $attributes,
