        my $ref_node_or_id = $context->($ref_label);

        # Get the node ID
        my $ref_id = ref($ref_node_or_id) ? $ref_node_or_id->id : $ref_node_or_id;

        # Create ScalarDeref node
        my $node_id = $self->next_node_id();
        my $deref = Chalk::IR::Node::ScalarDeref->new(
