    method build_hash_set_node($hash_node, $key_node, $value_node) {
        # Create HashSet node for setting hash value with context extension (immutable)
        my $node_id = $self->next_node_id();
        my $hash_set = Chalk::IR::Node::HashSet->new(
            id => $node_id,
