    my $loop_val_str = defined($loop_value) ? $loop_value : "undef";
    $phi->record_transform('ir_construction', 'Builder::build_loop_phi_node',
        context => "loop_id=" . $loop_node->id . ", initial=$initial_value, loop=$loop_val_str"
    );

    return $phi;
}

