    my $node_id = $self->next_node_id();
    my $reference = Chalk::IR::Node::Reference->new(
        id             => $node_id,
        inputs         => [$current_control, $collection_node->id, $index_node->id],
        target_context => $array_ctx,
        target_label   => $label,
    );
    $graph->add_node($reference);
    return $reference;
}

