        );
        $graph->add_node($cmp);

        # Record transformation
        $cmp->record_transform('ir_construction', 'Builder::build_less_or_equal_node',
            context => "left_id=" . $left_node->id . ", right_id=" . $right_node->id
        );

        return $cmp;
